<script>
const $ = id => document.getElementById(id);
const ACCENT = '#2e9bd6';

/* ---------------------------------------------------------------- map ---- */
const map = L.map('map', { zoomControl: true, attributionControl: true })
  .setView([47.95, 11.45], 10);
const layers = {
  poi: L.layerGroup().addTo(map),
  route: L.layerGroup().addTo(map),
  stops: L.layerGroup().addTo(map),
};
let layerDefs = [], layerIdx = 0, base = null;

function useLayer(i) {
  if (i >= layerDefs.length) return;
  layerIdx = i;
  const def = layerDefs[i];
  if (base) map.removeLayer(base);
  let errors = 0;
  base = L.tileLayer(def.url, { maxZoom: 19, attribution: def.attribution });
  base.on('tileerror', () => {
    if (++errors === 6 && i + 1 < layerDefs.length) useLayer(i + 1);
  });
  base.addTo(map);
  base.bringToBack();
}

async function api(url, body) {
  const r = await fetch(url, body ? {
    method: 'POST', headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body)
  } : {});
  const j = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(j.detail || r.statusText);
  return j;
}

/* --------------------------------------------------------- boot the map ---- */
(async () => {
  try {
    const mc = await api('/api/mapconfig');
    layerDefs = mc.layers;
  } catch {
    layerDefs = [{ url: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
                   attribution: '&copy; OpenStreetMap contributors' }];
  }
  useLayer(0);
  try {
    const p = await api('/api/ride/pois?limit=320');
    for (const poi of p.pois) {
      const r = poi.kind === 'lake' ? 5 : 3.2;
      L.circleMarker([poi.lat, poi.lon], {
        radius: r, weight: 1, color: 'rgba(233,237,242,.35)',
        fillColor: poi.kind === 'lake' ? '#4a90b8' : '#8b9099',
        fillOpacity: .5, interactive: true
      }).addTo(layers.poi).bindPopup(`<b>${poi.name}</b><br>${poi.kind}`);
    }
  } catch { /* POIs are decoration here; the ride still works without them */ }
})();

/* ------------------------------------------------------------- profile ---- */
let profile = null;

async function loadProfile(rider) {
  $('prof').innerHTML = '<div class="skel"></div><div class="skel"></div>';
  try {
    profile = await api('/api/ride/profile/' + rider);
    const p = profile;
    $('prof').className = 'prof';
    $('prof').innerHTML = `
      <div><span>Bike</span><b>${p.bike_class}</b>
        <div class="legend">${p.rpm_per_kmh} rpm per km/h, inferred</div></div>
      <div><span>Experience</span><b>${p.experience}</b>
        <div class="legend">${p.trips} rides, ${p.km_total.toLocaleString()} km</div></div>
      <div><span>Lean used</span><b class="num">${p.lean_p95}&deg;</b>
        <div class="legend">95th percentile while moving</div></div>
      <div><span>Safety ceiling</span><b class="num">${p.lean_ceiling}&deg;</b>
        <div class="legend">Roads beyond this leave your map</div></div>
      <div><span>Typical ride</span><b class="num">${p.typical_ride_min} min</b></div>
      <div><span>Ground covered</span><b class="num">${p.squares_ridden.toLocaleString()}</b>
        <div class="legend">100 m squares ridden</div></div>`;
  } catch (e) {
    $('prof').innerHTML = `<div class="msg bad">${e.message}</div>`;
  }
}

/* ------------------------------------------------ weather notification ---- */
let windows = [], chosen = 0;

function bars(score) {
  const n = Math.round(score * 5);
  return `<span class="bars">${[1,2,3,4,5].map(i =>
    `<i class="${i <= n ? 'on' : ''}" style="height:${5 + i * 2.6}px"></i>`).join('')}</span>`;
}

async function loadWeather(rider) {
  $('weather').className = 'stack';
  $('weather').innerHTML = '<div class="skel tall"></div><div class="skel" style="width:60%"></div>';
  try {
    const w = await api('/api/ride/windows?rider=' + rider);
    windows = w.windows || [];
    if (!windows.length) {
      $('weather').innerHTML = `<div class="msg">No rideable window in the next
        7 days. Nothing would be sent.</div>`;
      return;
    }
    render();
    if (w.home) map.setView([w.home.lat, w.home.lon], 11);
    L.marker([w.home.lat, w.home.lon], {
      icon: L.divIcon({ className: '', html: '<div class="home-marker"></div>',
                        iconSize: [15, 15], iconAnchor: [7, 7] })
    }).addTo(layers.stops).bindPopup('Home');
  } catch (e) {
    $('weather').innerHTML = `<div class="msg bad">${e.message}</div>`;
  }
}

function render() {
  const w = windows[chosen];
  const [s, e] = [new Date(w.start), new Date(w.end)];
  const hhmm = d => d.toTimeString().slice(0, 5);
  const today = new Date().toDateString();
  const tom = new Date(Date.now() + 864e5).toDateString();
  const day = s.toDateString() === today ? 'Today'
            : s.toDateString() === tom ? 'Tomorrow' : w.day;
  $('weather').className = '';
  $('weather').innerHTML = `
    <div class="alert">
      <div class="kicker">Good riding weather</div>
      <div class="when">${day}, ${hhmm(s)} to ${hhmm(e)}</div>
      <div class="cond"><b class="num">${w.temp_c}&deg;C</b> &middot;
        <b class="num">${w.rain_pct}%</b> chance of rain &middot;
        gusts <b class="num">${w.gust_kmh}</b> km/h</div>
      <button class="primary" id="plan">Plan a ${w.suggested_minutes} minute ride</button>
    </div>
    <div class="wins" id="wins"></div>`;
  $('wins').innerHTML = windows.slice(0, 5).map((x, i) => {
    const d = new Date(x.start);
    return `<button class="win" data-i="${i}" aria-pressed="${i === chosen}">
      <span><span class="d">${x.day}, ${hhmm(d)}</span>
      <span class="c"> ${x.hours}h at ${x.temp_c}&deg;C</span></span>
      ${bars(x.score)}</button>`;
  }).join('');
  for (const b of $('wins').querySelectorAll('.win'))
    b.onclick = () => { chosen = +b.dataset.i; render(); };
  $('plan').onclick = plan;
}

/* --------------------------------------------------------------- ride ---- */
async function plan() {
  const w = windows[chosen];
  const btn = $('plan');
  btn.disabled = true;
  btn.textContent = 'Finding roads worth the trip';
  $('ride').className = 'stack';
  $('ride').innerHTML = '<div class="skel tall"></div><div class="skel"></div>';
  try {
    const d = await api('/api/ride/suggest', {
      rider: $('riderSel').value, minutes: w.suggested_minutes,
      weather: Math.min(1, (w.rain_pct || 0) / 100),
    });
    drawRide(d);
  } catch (e) {
    $('ride').className = 'msg bad';
    $('ride').textContent = e.message;
  }
  btn.disabled = false;
  btn.textContent = `Plan a ${w.suggested_minutes} minute ride`;
}

function drawRide(d) {
  layers.route.clearLayers();
  layers.stops.clearLayers();
  const r = d.routes && d.routes[0];
  if (!r) {
    $('ride').className = 'msg';
    $('ride').textContent = d.reason || 'No ride fitted that window.';
    return;
  }
  L.polyline(r.coords, { color: '#05080b', weight: 8, opacity: .55 }).addTo(layers.route);
  L.polyline(r.coords, { color: ACCENT, weight: 4, opacity: .95 }).addTo(layers.route);

  L.marker(d.origin, { icon: L.divIcon({ className: '',
      html: '<div class="home-marker"></div>', iconSize: [15, 15], iconAnchor: [7, 7] })
  }).addTo(layers.stops).bindPopup('Home');

  (r.stops || []).forEach((s, i) => {
    L.marker([s.lat, s.lon], { icon: L.divIcon({ className: '',
        html: `<div class="stop-marker">${i + 1}</div>`,
        iconSize: [24, 24], iconAnchor: [12, 12] })
    }).addTo(layers.stops).bindPopup(`<b>${s.name}</b><br>${s.kind}`);
  });
  map.fitBounds(L.polyline(r.coords).getBounds(), { padding: [50, 50] });

  const k = r.kpis;
  const legs = r.legs || [];
  const stopRows = (r.stops || []).map((s, i) => `
    <div class="stop"><div class="pin">${i + 1}</div>
      <div><div class="nm">${s.name}</div><div class="kd">${s.kind}</div></div>
      <div class="km">${legs[i] ? legs[i].km + ' km' : ''}</div></div>`).join('');
  const back = legs.length ? legs[legs.length - 1].km : null;
  const t = r.value_thirds || [];
  const bestIdx = t.length ? t.indexOf(Math.max(...t)) : -1;

  $('rideSub').textContent = d.kind === 'scenic-chain'
    ? 'Out of town first, then the part you came for, then home.'
    : 'No scenic chain fitted this budget, so here is the best loop instead.';
  $('ride').className = '';
  $('ride').innerHTML = `
    <div class="ride-name">${r.label}</div>
