  // rather than as one more line on a busy map.
  document.getElementById('map').classList.toggle('fogged', on);
  const b = $('fogToggle');
  if (b) { b.setAttribute('aria-pressed', String(on));
           b.textContent = on ? 'Hide the fog map' : 'Show it on the map'; }
}

async function loadFog(rider) {
  $('fog').className = 'stack';
  $('fog').innerHTML = '<div class="skel"></div><div class="skel"></div>';
  layers.fog.clearLayers();
  layers.fogTargets.clearLayers();
  try {
    const d = await api('/api/ride/fog/' + rider);
    for (const [a, b, c, e] of d.ridden) {
      L.polyline([[a, b], [c, e]], {
        color: '#5eb9f0', weight: 2, opacity: .75, renderer: fogCanvas,
        interactive: false
      }).addTo(layers.fog);
    }
    for (const t of d.targets) {
      L.circleMarker([t.lat, t.lon], {
        radius: 7, color: '#d6a450', weight: 2, fillColor: '#d6a450',
        fillOpacity: .28, renderer: fogCanvas
      }).addTo(layers.fogTargets)
        .bindPopup(`<b>${t.name}</b><br>${t.km} km you have never ridden`);
    }

    $('fog').className = '';
    $('fog').innerHTML = `
      <div class="fogfig"><b class="num">${Math.round(d.ridden_km)}</b>
        <span>of ${Math.round(d.network_km).toLocaleString()} km ridden</span></div>
      <div class="fogbar"><i style="width:${d.pct}%"></i></div>
      <div class="legend">${d.pct}% of the good motorcycling road down here.</div>
      <button class="ghost" id="fogToggle" aria-pressed="false"
              style="margin-top:12px">Show it on the map</button>
      <div class="legend" style="margin-top:16px">Best roads you have never ridden</div>
      <div id="targets"></div>`;
    $('targets').innerHTML = d.targets.map((t, i) => `
      <button class="target" data-i="${i}">
        <span class="tn">${t.name}</span>
        <span><span class="tk">${t.km} km</span>
        &nbsp;<span class="tv">${t.value.toFixed(2)}</span></span>
      </button>`).join('');
    for (const b of $('targets').querySelectorAll('.target')) {
      const t = d.targets[+b.dataset.i];
      b.onclick = () => {
        if (!fogShown) toggleFog(true);
        map.setView([t.lat, t.lon], 13);
      };
    }
    $('fogToggle').onclick = () => toggleFog(!fogShown);
  } catch (e) {
    $('fog').className = 'msg bad';
    $('fog').textContent = e.message;
  }
}

