        # ring beyond the ring that could still hold a closer node is enough,
        # which is what keeps this EXACTLY equal to the old full sweep rather
        # than merely close to it.
        ring = 0
        settled = None
        while True:
            for dy in range(-ring, ring + 1):
                for dx in range(-ring, ring + 1):
                    # Only the newly added shell, not the whole square again.
                    if ring and max(abs(dy), abs(dx)) != ring:
                        continue
                    for node in self._node_grid.get((gy + dy, gx + dx), ()):
                        nlat, nlon = self._pos[node]
                        d = (nlat - lat) ** 2 + ((nlon - lon) * k) ** 2
                        if d < best_d:
