            if best is not None and settled is None:
                # Rings are NODE_CELL_DEG wide in latitude; convert the best
                # distance into how many rings could still beat it.
                reach = math.sqrt(best_d) / NODE_CELL_DEG
                settled = ring + int(reach) + 1
            if settled is not None and ring >= settled:
                return best
            ring += 1
            if ring > MAX_NODE_RINGS:
                return best

